"""
Holds all vanilla minecraft items/blocks/etc.
"""
from dataclasses import dataclass

@dataclass(frozen=True)
class Item:
    id: str
    display_name: str
    stack_size: int

@dataclass(frozen=True)
class Tier:
    id: str
    display_name: str
    uses: int
    speed: float
    attack_damage_bonus: float
    enchantment_value: int
    incorrect_blocks_for_drops: str
    repair_ingredient: str

